import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

const { fontFamily } = loadFont();



export type FrameworkPyramidProps = Record<string, any>;

const BackgroundGraphics: React.FC = () => {
  return (
    <AbsoluteFill style={{ pointerEvents: "none", opacity: 0.15 }}>
      <svg width="100%" height="100%">
        <defs>
          <pattern id="grid" width="60" height="60" patternUnits="userSpaceOnUse">
            <path d="M 60 0 L 0 0 0 60" fill="none" stroke="#ffffff" strokeWidth="0.5" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#grid)" />
        {/* Subtle decorative circuit lines */}
        <path d="M 200 1080 L 200 900 L 400 700 L 400 200" fill="none" stroke="#ffffff" strokeWidth="2" strokeDasharray="4 8" />
        <path d="M 1720 1080 L 1720 800 L 1520 600 L 1520 100" fill="none" stroke="#ffffff" strokeWidth="2" strokeDasharray="4 8" />
        <circle cx="400" cy="700" r="4" fill="#ffffff" />
        <circle cx="1520" cy="600" r="4" fill="#ffffff" />
      </svg>
    </AbsoluteFill>
  );
};

const LayerBlock: React.FC<{
  data: FrameworkPyramidProps["layers"][0];
  topWidth: number;
  baseWidth: number;
  topHeight: number;
  frontHeight: number;
  delay: number;
  frame: number;
  fps: number;
  isTopLayer: boolean;
}> = ({ data, topWidth, baseWidth, topHeight, frontHeight, delay, frame, fps, isTopLayer }) => {
  const leftPercent = ((baseWidth - topWidth) / 2 / baseWidth) * 100;
  const rightPercent = 100 - leftPercent;

  const animProgress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, mass: 1, stiffness: 120 },
  });

  const translateY = interpolate(animProgress, [0, 1], [60, 0]);
  const opacity = interpolate(frame - delay, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  const scale = interpolate(animProgress, [0, 1], [0.95, 1]);

  return (
    <div
      style={{
        width: baseWidth,
        display: "flex",
        flexDirection: "column",
        transform: `translateY(${translateY}px) scale(${scale})`,
        opacity,
        position: "relative",
      }}
    >
      {/* Top Face (Trapezoid) */}
      <div
        style={{
          width: "100%",
          height: topHeight,
          background: `linear-gradient(to right, ${data.colors.topL} 50%, ${data.colors.topR} 50%)`,
          clipPath: `polygon(${leftPercent}% 0, ${rightPercent}% 0, 100% 100%, 0% 100%)`,
          borderTop: "2px solid rgba(255, 255, 255, 0.3)",
          boxShadow: "inset 0px 10px 20px rgba(255, 255, 255, 0.1)",
        }}
      />

      {/* Front Face (Rectangle) */}
      <div
        style={{
          width: "100%",
          height: frontHeight,
          background: `linear-gradient(to right, ${data.colors.frontL} 50%, ${data.colors.frontR} 50%)`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          borderTop: "1px solid rgba(255, 255, 255, 0.6)",
          boxShadow: "0 25px 40px -10px rgba(0, 0, 0, 0.6)",
          position: "relative",
        }}
      >
        <span
          style={{
            fontFamily,
            color: "#ffffff",
            fontSize: 42,
            fontWeight: 600,
            letterSpacing: "0.02em",
            textShadow: "0 2px 10px rgba(0,0,0,0.3)",
            zIndex: 2,
          }}
        >
          {data.text}
        </span>

        {/* Central Glint Highlights */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: 140,
            height: 3,
            background: "radial-gradient(ellipse at center, #ffffff 0%, rgba(255,255,255,0) 70%)",
            zIndex: 3,
          }}
        />
        <div
          style={{
            position: "absolute",
            top: 0,
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: 3,
            height: 60,
            background: "radial-gradient(ellipse at center, rgba(255,255,255,0.9) 0%, rgba(255,255,255,0) 70%)",
            zIndex: 3,
          }}
        />
      </div>

      {/* Volumetric light beam on top layer */}
      {isTopLayer && (
        <div
          style={{
            position: "absolute",
            bottom: "100%",
            left: `${leftPercent}%`,
            width: `${rightPercent - leftPercent}%`,
            height: 250,
            background: "linear-gradient(to top, rgba(92, 227, 236, 0.15) 0%, rgba(92, 227, 236, 0) 100%)",
            pointerEvents: "none",
            transform: "translateY(2px)", // slightly overlap to prevent seam
          }}
        />
      )}
    </div>
  );
};

const FrameworkPyramid: React.FC<FrameworkPyramidProps> = ({
  backgroundColor = "#040F1E",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "The Framework",
  layers = [
    {
      text: "Layer 3: Escalation Triggers",
      colors: {
        topL: "#5CE3EC",
        topR: "#35BCC7",
        frontL: "#3AC8D2",
        frontR: "#20A0AA",
      },
    },
    {
      text: "Layer 2: Guardrails",
      colors: {
        topL: "#4BB2EC",
        topR: "#2A8BC4",
        frontL: "#3496CB",
        frontR: "#1872A4",
      },
    },
    {
      text: "Layer 1: Domain Sovereignty",
      colors: {
        topL: "#3D8ABF",
        topR: "#1C6496",
        frontL: "#2A6D9F",
        frontR: "#0D4972",
      },
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Radial gradient over the solid background color to add depth
  const compositeBg = transparentBackground 
    ? bgColor 
    : `radial-gradient(circle at 50% 60%, #112B47 0%, ${bgColor} 80%)`;

  // Base widths for the pyramid tiers (relative to 1920x1080 canvas)
  const widths = [
    width * 0.35, // Top edge of Layer 3
    width * 0.45, // Base of Layer 3 / Top of Layer 2
    width * 0.55, // Base of Layer 2 / Top of Layer 1
    width * 0.65, // Base of Layer 1
  ];

  const frontHeight = height * 0.085;
  const topHeight = height * 0.045;

  // Title Animation
  const titleDelay = 60;
  const titleOpacity = interpolate(frame - titleDelay, [0, 20], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(spring({ frame: frame - titleDelay, fps, config: { damping: 12 } }), [0, 1], [20, 0]);

  return (
    <AbsoluteFill style={{ background: compositeBg, overflow: "hidden" }}>
      {!transparentBackground && <BackgroundGraphics />}

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          height: "100%",
          width: "100%",
          position: "relative",
        }}
      >
        {/* Title */}
        <div
          style={{
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            marginBottom: 40,
            zIndex: 10,
          }}
        >
          <h1
            style={{
              fontFamily,
              color: "#E0FFFF",
              fontSize: 64,
              fontWeight: 600,
              margin: 0,
              textShadow: "0 0 20px rgba(92, 227, 236, 0.4), 0 4px 10px rgba(0,0,0,0.5)",
              letterSpacing: "0.01em",
            }}
          >
            {title}
          </h1>
        </div>

        {/* Pyramid Stack (Rendered Top to Bottom visually, which matches array order 0, 1, 2) */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
          {layers.map((layer, index) => {
            // Reverse delay so bottom layer (index 2) appears first (delay 10)
            const staggerDelay = 10 + (2 - index) * 15;
            
            return (
              <LayerBlock
                key={index}
                data={layer}
                topWidth={widths[index]}
                baseWidth={widths[index + 1]}
                topHeight={topHeight}
                frontHeight={frontHeight}
                delay={staggerDelay}
                frame={frame}
                fps={fps}
                isTopLayer={index === 0}
              />
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FrameworkPyramid;